-- Jnkie key -- per Junkie's own docs (docs.jnkie.com/roblox-sdk), their
-- SDK reads getgenv().SCRIPT_KEY, and it has to be set before whatever
-- loadstring initializes the Junkie-wrapped script -- not a bare local,
-- that was never going to be checked by anything. Set first, before even
-- the service GetService calls below, so nothing can run ahead of it.
getgenv().SCRIPT_KEY = "xgrs-f--8263c465-5bd0-4837-a311-ed2cf0d2e497"

local TweenService = game:GetService("TweenService")
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

-- The command users should run instead of the old jnkie-based loader.
-- Points at our own storage endpoint (api.xgrs.lol), which serves the
-- current loader.lua straight from the xgrs.lol key/licensing system.
local NEW_SCRIPT_COMMAND = 'loadstring(game:HttpGet("https://api.xgrs.lol/storage/xgrs-loader"))()'

-- Destroy any existing swaploader before creating a new one
local guiParent = (gethui and gethui()) or CoreGui or Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
for _, child in ipairs(guiParent:GetChildren()) do
    if child.Name == "XGRS_SwapNotice" then
        child:Destroy()
    end
end

local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = "XGRS_SwapNotice"
ScreenGui.ResetOnSpawn = false
ScreenGui.DisplayOrder = 999999999
ScreenGui.IgnoreGuiInset = true

local protect = protectgui or (syn and syn.protect_gui)
if protect then pcall(protect, ScreenGui) end
ScreenGui.Parent = guiParent

local MainFrame = Instance.new("Frame")
MainFrame.Size = UDim2.fromOffset(420, 198)
MainFrame.Position = UDim2.fromScale(0.5, 0.5)
MainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
MainFrame.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
MainFrame.BackgroundTransparency = 0.15
MainFrame.BorderSizePixel = 0
MainFrame.ClipsDescendants = true
MainFrame.Parent = ScreenGui

local UICorner = Instance.new("UICorner")
UICorner.CornerRadius = UDim.new(0, 12)
UICorner.Parent = MainFrame

local UIStroke = Instance.new("UIStroke")
UIStroke.Color = Color3.fromRGB(50, 50, 65)
UIStroke.Thickness = 1.5
UIStroke.Transparency = 0.2
UIStroke.Parent = MainFrame

-- Drag functionality
local dragging = false
local dragStart = nil
local startPos = nil

MainFrame.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = MainFrame.Position
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                dragging = false
            end
        end)
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - dragStart
        MainFrame.Position = UDim2.new(
            startPos.X.Scale, startPos.X.Offset + delta.X,
            startPos.Y.Scale, startPos.Y.Offset + delta.Y
        )
    end
end)

-- Close Button (Top Right)
local CloseButton = Instance.new("TextButton")
CloseButton.Size = UDim2.fromOffset(20, 20)
CloseButton.Position = UDim2.new(1, -30, 0, 10)
CloseButton.BackgroundTransparency = 1
CloseButton.Text = "×"
CloseButton.TextColor3 = Color3.fromRGB(150, 150, 160)
CloseButton.TextSize = 18
CloseButton.Font = Enum.Font.GothamBold
CloseButton.Modal = true
CloseButton.Parent = MainFrame

CloseButton.MouseEnter:Connect(function()
    TweenService:Create(CloseButton, TweenInfo.new(0.2), { TextColor3 = Color3.fromRGB(255, 100, 100) }):Play()
end)
CloseButton.MouseLeave:Connect(function()
    TweenService:Create(CloseButton, TweenInfo.new(0.2), { TextColor3 = Color3.fromRGB(150, 150, 160) }):Play()
end)
CloseButton.MouseButton1Click:Connect(function()
    ScreenGui:Destroy()
end)

