    TweenService:Create(CopyStroke, TweenInfo.new(0.2), { Transparency = 0.2 }):Play()
end)

-- Shared by both the Copy button and clicking the code preview itself --
-- one clipboard write, one feedback/reset cycle, so clicking either one
-- mid-animation can't leave the other's label stuck on a stale message.
local resetLabelThread = nil
local function copyScriptCommand()
    local set_clipboard = setclipboard or toclipboard
    local ok = set_clipboard and pcall(set_clipboard, NEW_SCRIPT_COMMAND)

    if ok then
        CopyLabel.Text = "Copied!"
        CodeLabel.Text = "Copied to clipboard!"
        StatusLabel.Text = "Copied! Paste it into your executor instead of the old script."
        StatusLabel.TextColor3 = Color3.fromRGB(100, 255, 100)
    elseif set_clipboard then
        CopyLabel.Text = "Copy Failed"
    else
        CopyLabel.Text = "Clipboard Unsupported"
    end

    if resetLabelThread then
        task.cancel(resetLabelThread)
    end
    resetLabelThread = task.delay(2.5, function()
        CopyLabel.Text = "Copy New Script"
        CodeLabel.Text = NEW_SCRIPT_COMMAND
        StatusLabel.Text = "We've switched to our own loader system.\nPlease use only the new script from now on!"
        StatusLabel.TextColor3 = Color3.fromRGB(200, 200, 215)
        resetLabelThread = nil
    end)
end

CopyButton.MouseButton1Click:Connect(copyScriptCommand)
CodeLabel.MouseButton1Click:Connect(copyScriptCommand)

-- Entrance animation
MainFrame.Size = UDim2.fromOffset(0, 0)
MainFrame.BackgroundTransparency = 1
UIStroke.Transparency = 1
